package dev.cardadvisor.auth;
import dev.cardadvisor.api.ApiError;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service @Transactional public class AccountRecoveryService {
 private final JdbcTemplate db;private final AccountMailGateway mail;private final RequestLimits limits;
 public AccountRecoveryService(JdbcTemplate d,AccountMailGateway m,RequestLimits l){db=d;mail=m;limits=l;}
 private void lock(UUID user){if(db.queryForList("SELECT id FROM app_users WHERE id=? FOR UPDATE",user).isEmpty())throw new ApiError(401,"SESSION_EXPIRED");}
 public Map<String,Object> status(UUID user){lock(user);var row=db.queryForMap("SELECT email_verified_at FROM app_users WHERE id=?",user);var out=new LinkedHashMap<String,Object>();out.put("emailVerified",row.get("email_verified_at")!=null);out.put("verifiedAt",row.get("email_verified_at"));out.put("mailConfigured",mail.ready());return out;}
 private void issue(UUID user,String purpose,String email){lock(user);limits.require("account-action:"+user+":"+purpose,3,900);String token=Passwords.randomToken();db.update("UPDATE account_action_tokens SET consumed_at=now() WHERE user_id=? AND purpose=? AND consumed_at IS NULL",user,purpose);db.update("INSERT INTO account_action_tokens(token_hash,user_id,purpose,expires_at) VALUES(?,?,?,now()+interval '15 minutes')",Passwords.sha(token),user,purpose);mail.send(email,purpose,token);}
 public Object requestVerification(UUID user){if(!mail.ready())throw new ApiError(503,"ACCOUNT_MAIL_UNAVAILABLE");lock(user);String email=db.queryForObject("SELECT email FROM app_users WHERE id=?",String.class,user);issue(user,"VERIFY_EMAIL",email);return Map.of("accepted",true,"expiresInSeconds",900);}
 public Object requestReset(String email){if(email==null||email.length()>254||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new ApiError(422,"INVALID_EMAIL_FORMAT");if(!mail.ready())throw new ApiError(503,"ACCOUNT_MAIL_UNAVAILABLE");String normalized=email.toLowerCase(Locale.ROOT);limits.require("password-reset:"+Passwords.sha(normalized),3,900);var users=db.queryForList("SELECT id,email FROM app_users WHERE email=?",normalized);if(!users.isEmpty())try{issue((UUID)users.get(0).get("id"),"RESET_PASSWORD",(String)users.get(0).get("email"));}catch(ApiError e){if(!"ACCOUNT_MAIL_DELIVERY_FAILED".equals(e.getMessage()))throw e;db.update("UPDATE account_action_tokens SET consumed_at=now() WHERE user_id=? AND purpose='RESET_PASSWORD' AND consumed_at IS NULL",users.get(0).get("id"));}return Map.of("accepted",true);}
 private UUID owner(String token,String purpose,UUID required){if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw new ApiError(422,"INVALID_ACCOUNT_ACTION");var owners=db.queryForList("SELECT user_id FROM account_action_tokens WHERE token_hash=? AND purpose=?",Passwords.sha(token),purpose);if(owners.isEmpty())throw new ApiError(401,"ACCOUNT_ACTION_REJECTED");UUID user=(UUID)owners.get(0).get("user_id");if(required!=null&&!required.equals(user))throw new ApiError(401,"ACCOUNT_ACTION_REJECTED");lock(user);var tokenRows=db.queryForList("SELECT token_hash FROM account_action_tokens WHERE token_hash=? AND purpose=? AND user_id=? AND consumed_at IS NULL AND expires_at>now() FOR UPDATE",Passwords.sha(token),purpose,user);if(tokenRows.isEmpty())throw new ApiError(401,"ACCOUNT_ACTION_REJECTED");return user;}
 public Object verify(UUID user,String token){owner(token,"VERIFY_EMAIL",user);db.update("UPDATE app_users SET email_verified_at=COALESCE(email_verified_at,now()) WHERE id=?",user);db.update("UPDATE account_action_tokens SET consumed_at=now() WHERE token_hash=?",Passwords.sha(token));return status(user);}
 public Object reset(String token,String password){if(password==null||password.length()<12||password.length()>128)throw new ApiError(422,"INVALID_PASSWORD_FORMAT");UUID user=owner(token,"RESET_PASSWORD",null);String hash=Passwords.hash(password);db.update("UPDATE app_users SET password_hash=?,revision=revision+1 WHERE id=?",hash,user);db.update("UPDATE account_action_tokens SET consumed_at=now() WHERE user_id=? AND purpose='RESET_PASSWORD' AND consumed_at IS NULL",user);db.update("DELETE FROM sessions WHERE user_id=?",user);db.update("UPDATE refresh_sessions SET revoked_at=now() WHERE user_id=?",user);return Map.of("passwordChanged",true,"allSessionsRevoked",true);}
}
